```tsx
import { useId } from "react";
import "./FocusProgress.css";

export interface FocusProgressProps {
  label: string;
  elapsedMinutes: number;
  totalMinutes: number;
}

export function FocusProgress({
  label,
  elapsedMinutes,
  totalMinutes,
}: FocusProgressProps) {
  const labelId = useId();

  const total =
    Number.isFinite(totalMinutes) && totalMinutes > 0 ? totalMinutes : 0;
  const elapsed = Number.isFinite(elapsedMinutes)
    ? Math.min(Math.max(elapsedMinutes, 0), total)
    : 0;
  const percent = total === 0 ? 0 : (elapsed / total) * 100;

  const shownElapsed = Math.round(elapsed);
  const shownTotal = Math.round(total);
  const summary = `${shownElapsed} of ${shownTotal} min`;

  return (
    <div className="focus-progress">
      <div className="focus-progress__header">
        <span className="focus-progress__label" id={labelId}>
          {label}
        </span>
        <span className="focus-progress__readout" aria-hidden="true">
          {summary}
        </span>
      </div>

      <div
        className="focus-progress__track"
        role="progressbar"
        tabIndex={0}
        aria-labelledby={labelId}
        aria-valuemin={0}
        aria-valuemax={shownTotal}
        aria-valuenow={shownElapsed}
        aria-valuetext={summary}
      >
        <div
          className="focus-progress__fill"
          style={{ width: `${percent}%` }}
        />
      </div>
    </div>
  );
}
```

