.focus-progress {
  font: inherit;
  color: var(--ink);
  display: grid;
  gap: clamp(0.4rem, 0.8vw, 0.6rem);
  width: 100%;
}

.focus-progress__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.focus-progress__label {
  font-size: clamp(0.875rem, 1.2vw, 1.05rem);
  font-weight: 600;
  color: var(--ink);
}

.focus-progress__readout {
  font-size: clamp(0.8rem, 1.1vw, 0.95rem);
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.focus-progress__track {
  position: relative;
  height: clamp(0.5rem, 1vw, 0.75rem);
  border-radius: 999px;
  background: var(--axon-ahead);
  overflow: hidden;
}

.focus-progress__fill {
  height: 100%;
  width: 0;
  border-radius: 999px;
  background: var(--myelin);
  transition: width 400ms ease;
}

:root[data-motion="reduce"] .focus-progress__fill {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .focus-progress__fill {
    transition: none;
  }
}
